package com.personal.jobagent.discovery;
import org.junit.jupiter.api.Test;import java.util.List;import static org.assertj.core.api.Assertions.assertThat;
class ExtractionComparisonServiceTest {private final ExtractionComparisonService service=new ExtractionComparisonService();private ScraperProvider.ExtractedJob job(String t,String c){return new ScraperProvider.ExtractedJob(t,c,"London","HYBRID",null,"FULL_TIME","Build systems",List.of("Java"),"https://example.test/jobs/1","https://example.test/jobs/1",null,"1","hash",.8,null);}@Test void identicalPrimaryResultsAgree(){var r=service.compare(job("Software Engineer","Acme"),job("software engineer","ACME"),.20);assertThat(r.agreement()).isTrue();assertThat(r.needsVerification()).isFalse();}@Test void materiallyDifferentTitleRequiresVerification(){var r=service.compare(job("Software Engineer","Acme"),job("Senior Software Engineer","Acme"),.20);assertThat(r.agreement()).isFalse();assertThat(r.needsVerification()).isTrue();assertThat(r.fields()).anyMatch(f->f.field().equals("title")&&!f.agreement());}}
